template <class B>
inline dagr::Bytes Arena::serialize(B& b, dagr::GraphCaches& caches) {
  b.reset();
  caches.reset();
  if (!live_message(root_)) {
    b.fail(dagr::Status::invalid_value);   // no root
    return b.bytes();
  }
  dagr::GraphWriter<B> w(b, caches);
  const dagr::NodeRef r = detail::Serde::store_message(w, *this, root_);
  dagr::store_graph_framing_at(b, r.off, 1);
  return b.bytes();
}

template <class B>
inline dagr::Bytes Arena::serialize(B& b) {
  dagr::GraphCaches caches;
  return serialize(b, caches);
}

inline dagr::Status Arena::restore(dagr::Bytes buf, std::size_t max_depth) {
  *this = Arena();
  const auto opened = ::benchmark_v2::message_frozen_graph::open_message_frozen_graph(buf);
  if (!opened.ok()) return opened.status();
  dagr::RestoreSeen seen(max_depth);
  root_ = detail::Serde::restore_message(*this, seen, opened.value());
  if (seen.status() != dagr::Status::ok) {
    *this = Arena();
    return seen.status();
  }
  return dagr::Status::ok;
}

